'use strict';

/**
 * Sound effects, by name. Each name is an MP3 in the repo's audio/ folder
 * (generated by tools/make_sounds.py), served over HTTPS from the jsDelivr CDN,
 * which mirrors public GitHub repos.
 *
 * - Change where files are served from with the SOUND_BASE_URL environment
 *   variable (it must end in a slash), e.g. your own S3 bucket.
 * - An adventure can add or override names with `sounds: { name: url }`;
 *   values may be full https:// or soundbank:// URLs, or another file name.
 * - Alexa needs MP3 at 48 kbps and 16, 22.05 or 24 kHz, at most 240 seconds per response.
 */

// Pinned to the commit that added these files, so the CDN serves exactly them.
// When you change the sounds, commit and push, then put the new commit ID here
// (a tag such as @sounds-v2 works too).
const DEFAULT_BASE = 'https://cdn.jsdelivr.net/gh/JonathanWacks/fightingfantasy@1b777212ac8add2f6a2aa3c9a0a050c860444998/audio/';

const SOUND_FILES = [
  'battle', 'bell', 'blast', 'clash', 'darts', 'death', 'door_creak', 'door_creak_long',
  'door_open', 'door_shut', 'drink', 'drips', 'drone', 'droplets', 'drumroll', 'footsteps',
  'ghost', 'ghost_wail', 'growl', 'hit', 'hurt', 'lucky', 'magic', 'march', 'roar', 'rowing',
  'running', 'storm', 'swing', 'thunder', 'unlucky', 'victory', 'wading', 'wind', 'wolf',
];

/** Sounds the engine plays on game events. Set an entry to null to silence it. */
const EVENTS = {
  combatStart: 'battle',
  round: 'swing',
  playerHits: 'hit',
  playerHurt: 'hurt',
  test: 'drumroll',
  lucky: 'lucky',
  unlucky: null,
  drink: 'drink',
  win: 'victory',
  death: 'death',
};

function baseUrl() {
  return process.env.SOUND_BASE_URL || DEFAULT_BASE;
}

const isUrl = (s) => /^(soundbank|https):\/\//.test(s);

/** Resolve a name (or a full URL) to a playable URL, or null if unknown. */
function soundUrl(name, overrides) {
  if (!name) return null;
  if (isUrl(name)) return name;
  const own = overrides && overrides[name];
  if (own) return isUrl(own) ? own : soundUrl(own);
  return SOUND_FILES.indexOf(name) !== -1 ? baseUrl() + name + '.mp3' : null;
}

module.exports = { SOUND_FILES, EVENTS, soundUrl, DEFAULT_BASE };
